import json
import jsonschema
from openai import OpenAI

client = OpenAI()

# 1. 定义目标结构
schema = {
    "type": "object",
    "properties": {
        "city": {"type": "string"},
        "temperature": {"type": "number"},
        "unit": {"type": "string", "enum": ["celsius", "fahrenheit"]},
        "forecast": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "day": {"type": "string"},
                    "high": {"type": "number"},
                    "low": {"type": "number"}
                },
                "required": ["day", "high", "low"],
                "additionalProperties": False
            }
        }
    },
    "required": ["city", "temperature", "unit", "forecast"],
    "additionalProperties": False
}

# 2. 调用 API（strict=True 时底层用约束解码）
response = client.chat.completions.create(
    model="gpt-4o-2024-08-06",
    messages=[{"role": "user", "content": "北京未来 3 天天气，返回结构化数据"}],
    response_format={
        "type": "json_schema",
        "json_schema": {"name": "weather", "schema": schema, "strict": True}
    }
)
raw_text = response.choices[0].message.content

# 3. 工程兜底：约束解码保证可解析 + schema 校验 + 业务语义检查
try:
    obj = json.loads(raw_text)                # 约束解码保证这步不会失败
    jsonschema.validate(obj, schema)          # 再验 schema（防御性）
    # 业务语义校验：schema 无法约束的
    if obj["unit"] == "celsius" and obj["temperature"] > 60:
        raise ValueError("温度异常：摄氏度超 60")
    if len(obj["forecast"]) != 3:
        raise ValueError(f"预期 3 天预报，实际 {len(obj['forecast'])} 条")
except (json.JSONDecodeError, jsonschema.ValidationError, ValueError) as e:
    # 重试、降级或人工兜底
    print(f"校验失败: {e}")
